import { chromium } from "playwright";
import { createServer } from "http";
import { readFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";
import { mkdir, rename, readdir } from "fs/promises";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, "..");
const testingDir = join(root, "testing");

function startServer() {
  return new Promise((resolve) => {
    const server = createServer((req, res) => {
      const file = req.url === "/" ? "/index.html" : req.url;
      const path = join(root, file);
      try {
        const content = readFileSync(path);
        const ext = path.split(".").pop();
        const types = { html: "text/html", css: "text/css", js: "application/javascript" };
        res.writeHead(200, { "Content-Type": types[ext] || "text/plain" });
        res.end(content);
      } catch {
        res.writeHead(404);
        res.end("Not found");
      }
    });
    server.listen(0, "127.0.0.1", () => {
      const { port } = server.address();
      resolve({ server, port });
    });
  });
}

async function main() {
  await mkdir(testingDir, { recursive: true });

  const { server, port } = await startServer();
  const url = `http://127.0.0.1:${port}/`;

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1280, height: 720 },
    recordVideo: { dir: testingDir, size: { width: 1280, height: 720 } },
  });

  const page = await context.newPage();
  await page.goto(url, { waitUntil: "networkidle" });
  await page.waitForTimeout(6000);

  const video = page.video();
  await context.close();
  await browser.close();
  server.close();

  const rawPath = await video.path();
  const destPath = join(testingDir, "agentic-ide-landing-evidence.webm");
  await rename(rawPath, destPath);

  console.log(`Video saved to: ${destPath}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

